"use client";

import { BlockEditor } from "@/components/block-editor/block-editor";
import { SlashCommand, getSlashCommandSuggestion } from "@/components/block-editor/extensions";
import { Callout } from "@/components/extensions/callout";
import { CodeBlock } from "@/components/extensions/code-block";
import {
  ImagePlaceholder,
  ResizableImage,
} from "@/components/extensions/image-placeholder";
import { Markdown } from "@/components/extensions/markdown";
import { Mention } from "@/components/extensions/mention";
import type { MentionItem } from "@/components/extensions/mention";
import { PasteCleanup } from "@/components/extensions/paste-cleanup";
import { Table } from "@/components/extensions/table";
import { TableHoverOverlay } from "@/components/extensions/table/table-hover-overlay";
import { Color } from "@tiptap/extension-color";
import { Highlight } from "@tiptap/extension-highlight";
import { Link } from "@tiptap/extension-link";
import { Placeholder } from "@tiptap/extension-placeholder";
import { TaskItem } from "@tiptap/extension-task-item";
import { TaskList } from "@tiptap/extension-task-list";
import { TextAlign } from "@tiptap/extension-text-align";
import { TextStyle } from "@tiptap/extension-text-style";
import { Underline } from "@tiptap/extension-underline";
import { useEditor } from "@tiptap/react";
import type { Content, JSONContent } from "@tiptap/react";
import { StarterKit } from "@tiptap/starter-kit";

import { cn } from "@/lib/utils";

import { createSlashItems } from "./slash-items";

import "@/components/block-editor/style.css";
import "@/components/extensions/callout/style.css";
import "@/components/extensions/code-block/style.css";
import "@/components/extensions/image-placeholder/style.css";
import "@/components/extensions/mention/style.css";
import "@/components/extensions/table/style.css";
import "@/components/extensions/ui/style.css";

export interface FullBlockEditorProps {
  className?: string;
  content?: Content;
  markdownFilename?: string;
  onChange?: (content: JSONContent) => void;
  placeholder?: string;
  searchUsers?: (query: string) => MentionItem[] | Promise<MentionItem[]>;
}

export const FullBlockEditor = ({
  className,
  content,
  markdownFilename = "document.md",
  onChange,
  placeholder = "Type / for commands...",
  searchUsers = () => [],
}: FullBlockEditorProps) => {
  const editor = useEditor({
    content,
    extensions: [
      StarterKit.configure({
        codeBlock: false,
        heading: { levels: [1, 2, 3] },
        link: false,
        underline: false,
      }),
      Placeholder.configure({ placeholder }),
      Underline,
      TextStyle,
      Color.configure({ types: ["textStyle"] }),
      Highlight.configure({ multicolor: true }),
      TaskList,
      TaskItem.configure({ nested: true }),
      CodeBlock,
      Callout,
      SlashCommand.configure({
        suggestion: getSlashCommandSuggestion(
          createSlashItems(markdownFilename)
        ),
      }),
      TextAlign.configure({ types: ["heading", "paragraph"] }),
      Table.configure({ resizable: true }),
      ResizableImage,
      ImagePlaceholder,
      Markdown.configure({ pasteMarkdown: true }),
      PasteCleanup,
      Mention.configure({
        debounce: 0,
        heading: "People",
        items: searchUsers,
      }),
      Link.configure({
        autolink: true,
        defaultProtocol: "https",
        openOnClick: true,
        protocols: ["http", "https"],
      }),
    ],
    immediatelyRender: false,
    onUpdate: ({ editor: current }) => onChange?.(current.getJSON()),
    shouldRerenderOnTransaction: false,
  });

  return (
    <div className={cn("relative", className)}>
      <BlockEditor editor={editor} className="px-2" />
      <TableHoverOverlay editor={editor} />
    </div>
  );
};

"use client";

import { defaultSlashCommandItems } from "@/components/block-editor/extensions";
import type { SlashCommandSuggestionItem } from "@/components/block-editor/extensions";
import {
  downloadMarkdown,
  importMarkdownFile,
} from "@/components/extensions/markdown";
import {
  FileDown,
  FileUp,
  ImageIcon,
  MessageSquareWarning,
  TableIcon,
} from "lucide-react";

export const createSlashItems = (
  markdownFilename: string
): SlashCommandSuggestionItem[] => [
  ...defaultSlashCommandItems,
  {
    command: ({ editor, range }) => {
      editor.chain().focus().deleteRange(range).insertImagePlaceholder().run();
    },
    description: "Insert an image placeholder you can fill in.",
    icon: <ImageIcon />,
    id: "image",
    keywords: ["image", "img", "picture", "photo"],
    title: "Image",
  },
  {
    command: ({ editor, range }) => {
      editor
        .chain()
        .focus()
        .deleteRange(range)
        .insertTable({ cols: 3, rows: 3, withHeaderRow: true })
        .run();
    },
    description: "Insert a table.",
    icon: <TableIcon />,
    id: "table",
    keywords: ["table", "grid"],
    title: "Table",
  },
  {
    command: ({ editor, range }) => {
      editor
        .chain()
        .focus()
        .deleteRange(range)
        .setCallout({ variant: "info" })
        .run();
    },
    description: "Highlight a note, tip, or warning.",
    icon: <MessageSquareWarning />,
    id: "callout",
    keywords: ["callout", "note", "tip", "warning", "alert", "info"],
    title: "Callout",
  },
  {
    command: ({ editor, range }) => {
      editor.chain().focus().deleteRange(range).run();
      importMarkdownFile(editor);
    },
    description: "Replace the document with a .md file.",
    icon: <FileUp />,
    id: "importMarkdown",
    keywords: ["markdown", "md", "import", "upload"],
    title: "Import Markdown",
  },
  {
    command: ({ editor, range }) => {
      editor.chain().focus().deleteRange(range).run();
      downloadMarkdown(editor, markdownFilename);
    },
    description: "Download the document as a .md file.",
    icon: <FileDown />,
    id: "exportMarkdown",
    keywords: ["markdown", "md", "export", "download"],
    title: "Export Markdown",
  },
];
